    /// Create an event. Returns (event, was_idempotent_replay).
    #[expect(
        clippy::too_many_arguments,
        reason = "Lab helper mirrors the event request fields"
    )]
    async fn create_event(
        &self,
        calendar_id: i64,
        title: Option<String>,
        description: Option<String>,
        location: Option<String>,
        start_utc: Option<i64>,
        end_utc: Option<i64>,
        idempotency_key: Option<&str>,
    ) -> Result<(Event, bool), String> {
        let mut st = self.inner.write().await;
        if let Some(key) = idempotency_key
            && let Some(&existing_id) = st.idempotency_keys.get(key)
            && let Some(ev) = st.events.get(&existing_id)
        {
            return Ok((ev.clone(), true));
        }
        let id = st.next_event_id;
        st.next_event_id += 1;
        let event = Event {
            id,
            calendar_id,
            title,
            description,
            location,
            status: "confirmed".to_string(),
            event_kind: "default".to_string(),
            start_utc,
            end_utc,
            version: 1,
        };
        st.events.insert(id, event.clone());
        if let Some(key) = idempotency_key {
            st.idempotency_keys.insert(key.to_string(), id);
        }
        Ok((event, false))
    }

    /// Update an event with optimistic concurrency. Returns the updated event.
    #[expect(
        clippy::too_many_arguments,
        reason = "Lab helper mirrors the event request fields"
    )]
    async fn update_event(
        &self,
        calendar_id: i64,
        event_id: i64,
        expected_version: i64,
        title: Option<String>,
        description: Option<String>,
        location: Option<String>,
        start_utc: Option<i64>,
        end_utc: Option<i64>,
    ) -> Result<Event, String> {
        let mut st = self.inner.write().await;
        let ev = st
            .events
            .get_mut(&event_id)
            .filter(|e| e.calendar_id == calendar_id)
            .ok_or_else(|| "event_not_found".to_string())?;
        if ev.version != expected_version {
            return Err("version_conflict".to_string());
        }
        if let Some(t) = title {
            ev.title = Some(t);
        }
        if let Some(d) = description {
            ev.description = Some(d);
        }
        if let Some(l) = location {
            ev.location = Some(l);
        }
        if let Some(s) = start_utc {
            ev.start_utc = Some(s);
        }
        if let Some(e) = end_utc {
            ev.end_utc = Some(e);
        }
        ev.version += 1;
        Ok(ev.clone())
    }

